import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const d=JSON.parse(`{"title":"Page 2 - js | Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"js/page/2","tag":"js","title":"Page 2 - js | Tag","prev":"/tags/js/","next":"/tags/js/page/3/","posts":[{"title":"如何封装第三方vue组件","url":"/posts/2018-05-29-wrapper-vue-component/","date":"2018-05-29 23:19","tags":["js","vue"],"html":"<p>终于算是正式接触 SPA 的前端工作了，最近在解决很多 Vue 组件的问题，其中就有一个针对第三方组件的定制化需求，花了不少时间来折腾。</p>\\n<h2 id=\\"解决-v-model-绑定\\" tabindex=\\"-1\\">解决 v-model 绑定 <a class=\\"header-anchor\\" href=\\"#解决-v-model-绑定\\" aria-label=\\"Permalink to &quot;解决 v-model 绑定&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这次封装的就是 element 的前端 vue 框架，因为框架本身对 iOS 兼容性不好，所以需要二次封装。封装的是一个 select 组件。所以需要数据的双向绑定，官方教程也已经解释了。\\n<a href=\\"https://vuejs.org/v2/guide/components-custom-events.html#Customizing-Component-v-model\\" target=\\"_blank\\" rel=\\"noreferrer\\">v-model</a> 本质上就是绑定一个值和监听相应的事件。\\n这次本质是封装的一个 input 元素，所以我们需要手动绑定 value 和监听事件。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#6F42C1\\"> v-bind:value</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"value\\"</span><span style=\\"color:#6F42C1\\"> v-on</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$listeners\\"</span><span style=\\"color:#24292E\\">>&#x3C;/</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>官方文档也解释了这个内置变量的用法<a href=\\"https://vuejs.org/v2/api/#vm-listeners\\" target=\\"_blank\\" rel=\\"noreferrer\\">vm-listeners</a></p>\\n<h2 id=\\"继承父元素的属性\\" tabindex=\\"-1\\">继承父元素的属性 <a class=\\"header-anchor\\" href=\\"#继承父元素的属性\\" aria-label=\\"Permalink to &quot;继承父元素的属性&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>父元素的属性继承可以使用<code>v-bind=&quot;$attrs&quot;</code>来完成。所以完成组建的透明封装只需要加上三个指令。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#6F42C1\\"> v-bind</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$attrs\\"</span><span style=\\"color:#6F42C1\\"> v-bind:value</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"value\\"</span><span style=\\"color:#6F42C1\\"> v-on</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$listeners\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>虽然知道答案之后很简单，但是探索的过程中还是比较花时间的。希望能帮助大家解决这个问题，如果有什么疏漏之处，也请大家指正。</p>\\n"},{"title":"JavaScript开发中的性能优化","url":"/posts/2018-04-25-javascript-performance/","date":"2018-04-25 23:22","tags":["js","performance"],"html":"<p>最近工作比较清闲，5 月又换了一个工作环境。总结下最近看的有关 JavaScript 性能的知识，并记下来供未来的自己参考。希望自己能不忘初心，继续成长！</p>\\n<h2 id=\\"使用-requestanimationframe-来更新动画\\" tabindex=\\"-1\\">使用 requestAnimationFrame 来更新动画 <a class=\\"header-anchor\\" href=\\"#使用-requestanimationframe-来更新动画\\" aria-label=\\"Permalink to &quot;使用 requestAnimationFrame 来更新动画&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>使用<code>requestAnimationFrame</code>把动画渲染交给浏览器，可以保证渲染保持在 60FPS。应该避免使用<code>setTimeout</code>或者<code>setInterval</code>来实现动画，因为计时器和事件队列会消耗更多的资源，还会导致无用的页面重新绘制。</p>\\n<h2 id=\\"使用-web-workers-来进行复杂的运算\\" tabindex=\\"-1\\">使用 Web Workers 来进行复杂的运算 <a class=\\"header-anchor\\" href=\\"#使用-web-workers-来进行复杂的运算\\" aria-label=\\"Permalink to &quot;使用 Web Workers 来进行复杂的运算&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>可以把单纯的计算放在 Web Workers 中，这样不影响主页面的渲染和流畅，例如加密和矩阵变换的运算就可以完全放在 Web Workers 中来减少主线程的执行时间，避免浏览器渲染堵塞。</p>\\n<h2 id=\\"避免微优化-javascript\\" tabindex=\\"-1\\">避免微优化 JavaScript <a class=\\"header-anchor\\" href=\\"#避免微优化-javascript\\" aria-label=\\"Permalink to &quot;避免微优化 JavaScript&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>举个最简单的例子，我曾经在一本书上看到过一个提升程序效率的例子。大致是这样的：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> array </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> array.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(array[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>这里的<code>array.length</code>获取数组的长度，每次都要计算数组长度会消耗不少时间，优化之后的代码是这样的：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> array </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> len </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> array.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> len; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(array[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>通过缓存数组的长度来保证只计算一次。这就是典型的微优化，说实话这段代码我一直在用，直到最近读了其他的书才发现，现在的 JS 解释器早就优化了对数组长度的计算。无论是读取一次还是一万次消耗的时间都没有太大差别。微优化应该是 JS 引擎需要做的事情，我们不应该在实际开发中在这方面耗费过多的时间。</p>\\n<h2 id=\\"滑动事件优化\\" tabindex=\\"-1\\">滑动事件优化 <a class=\\"header-anchor\\" href=\\"#滑动事件优化\\" aria-label=\\"Permalink to &quot;滑动事件优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当用户监听滑动事件并执行相关动画操作的时候，记得使用<code>window.requestAnimationFrame</code>来优化动画的执行。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> onScroll</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">evt</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // Prevent multiple rAF callbacks.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (scheduledAnimationFrame) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  scheduledAnimationFrame </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  requestAnimationFrame</span><span style=\\"color:#24292E\\">(readAndUpdatePage);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> readAndUpdatePage</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // do something</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  requestAnimationFrame</span><span style=\\"color:#24292E\\">(readAndUpdatePage);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">addEventListener</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'scroll'</span><span style=\\"color:#24292E\\">, onScroll);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br></div></div><p>参考：</p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/debounce-your-input-handlers\\" target=\\"_blank\\" rel=\\"noreferrer\\">Debounce Your Input Handlers</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/optimize-javascript-execution\\" target=\\"_blank\\" rel=\\"noreferrer\\">Optimize JavaScript Execution</a></p>\\n"},{"title":"JavaScript中的数据类型","url":"/posts/2018-01-16-javascript-types/","date":"2018-01-16 22:44","tags":["js"],"html":"<p>隔了一个月，我又来发博客了。最近的工作老是在写 CSS 和 HTML。但是我更想学习 JS 啊！我一直都觉得 HTML 和 CSS 是属于设计范畴的，而 JS 才是真正属于工程师的逻辑范畴。\\n况且最近 Github 上有一个神奇的项目<a href=\\"https://github.com/emilwallner/Screenshot-to-code-in-Keras\\" target=\\"_blank\\" rel=\\"noreferrer\\">Screenshot-to-code-in-Keras</a>可以把截图直接生成 HTML 代码，我觉得只是单纯的从 PSD 翻译成页面的工作迟早要被淘汰。</p>\\n<p>最近在读 You Don't Know JS 这本书。书上讲解了很多关于 JS 的细节知识，对于深入了解 JS 有很大帮助。所以想在读的过程中把一些觉得有意思的东西记下来，便于以后复习。</p>\\n<h2 id=\\"类型\\" tabindex=\\"-1\\">类型 <a class=\\"header-anchor\\" href=\\"#类型\\" aria-label=\\"Permalink to &quot;类型&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>JavaScript 中有七种内置类型：</p>\\n<ol>\\n<li>空值(null)</li>\\n<li>未定义(undefined)</li>\\n<li>布尔值(boolean)</li>\\n<li>数字(number)</li>\\n<li>字符串(string)</li>\\n<li>对象(object)</li>\\n<li>符号(symbol, ES6 新增)</li>\\n</ol>\\n<p>除了对象之外，通称基本类型。</p>\\n<h2 id=\\"javascript-中的设计-bug\\" tabindex=\\"-1\\">JavaScript 中的设计 BUG <a class=\\"header-anchor\\" href=\\"#javascript-中的设计-bug\\" aria-label=\\"Permalink to &quot;JavaScript 中的设计 BUG&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">typeof</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#D73A49\\"> ===</span><span style=\\"color:#032F62\\"> 'object'</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#6A737D\\">// true</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>正确的返回结果应该是 null。但这个 BUG 由来已久，修复反而会出问题。所以我们需要使用复合条件来判断：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">a </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> a </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'object'</span><span style=\\"color:#24292E\\">;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来是<code>NaN</code>的问题：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> a </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 2</span><span style=\\"color:#D73A49\\"> /</span><span style=\\"color:#032F62\\"> 'foo'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> b </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'foo'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">a; </span><span style=\\"color:#6A737D\\">// NaN</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b; </span><span style=\\"color:#6A737D\\">// \\"foo\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">isNaN</span><span style=\\"color:#24292E\\">(a); </span><span style=\\"color:#6A737D\\">// true</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">isNaN</span><span style=\\"color:#24292E\\">(b); </span><span style=\\"color:#6A737D\\">// true</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">NaN</span><span style=\\"color:#D73A49\\"> ===</span><span style=\\"color:#005CC5\\"> NaN</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#6A737D\\">// false</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>很显然&quot;foo&quot;不是 NaN，但显然它也不是数字。这个 BUG 也存在很久了，在 ES6 时代，我们可以使用 <code>Number.isNaN</code> 来解决。\\nES6 之前的 polyfill 是：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">Number.isNaN) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  Number.</span><span style=\\"color:#6F42C1\\">isNaN</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">n</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> n </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'number'</span><span style=\\"color:#D73A49\\"> &#x26;&#x26;</span><span style=\\"color:#24292E\\"> window.</span><span style=\\"color:#6F42C1\\">isNaN</span><span style=\\"color:#24292E\\">(n);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>并且 NaN 是 JS 中唯一一个不等于自身的值。</p>\\n<h2 id=\\"值和类型\\" tabindex=\\"-1\\">值和类型 <a class=\\"header-anchor\\" href=\\"#值和类型\\" aria-label=\\"Permalink to &quot;值和类型&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>JavaScript 中的变量是没有类型的，只有值才有。变量可以随时持有任何类型的值。</p>\\n<p>undefined 和 undeclared. 变量在未持有的时候为 undefined, 此时 typeof 返回 undefined. 大多数开发者倾向于将 undefined 等同于 undeclared(未声明),但在 JavaScript 中它们完全是两回事。已在作用域中声明但还没有赋值的变量,是 undefined 的。相反,还没有在作用域中声明过的变量,是 undeclared 的。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> a;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">a; </span><span style=\\"color:#6A737D\\">// undefined</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b; </span><span style=\\"color:#6A737D\\">// ReferenceError: b is not defined</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">typeof</span><span style=\\"color:#24292E\\"> a; </span><span style=\\"color:#6A737D\\">// \\"undefined\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">typeof</span><span style=\\"color:#24292E\\"> b; </span><span style=\\"color:#6A737D\\">// \\"undefined\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>虽然 b 是一个 undeclared 变量,但 typeof b 并没有报错。这是因为 typeof 有一个特殊的安全防范机制。防止因为未定义导致程序终止运行。</p>\\n<h2 id=\\"值和引用\\" tabindex=\\"-1\\">值和引用 <a class=\\"header-anchor\\" href=\\"#值和引用\\" aria-label=\\"Permalink to &quot;值和引用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在许多编程语言中，赋值和参数传递可以通过值复制(value-copy)或者引用复制(reference-copy)来完成，这取决与我们使用什么语法。但是 JavaScript 对值和引用的赋值 / 传递在语法上没有区别,完全根据值的类型来决定。</p>\\n<p>简单值(即标量基本类型值,scalar primitive)总是通过值复制的方式来赋值/传递,包括 null 、 undefined 、字符串、数字、布尔和 ES6 中的 symbol 。</p>\\n<p>复合值(compound value)——对象(包括数组和封装对象)和函数,则总是通过引用复制的方式来赋值/传递。由于引用指向的是值本身而非变量,所以一个引用无法更改另一个引用的指向。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> a </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> b </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> a;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">a; </span><span style=\\"color:#6A737D\\">//[1,2,3]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b; </span><span style=\\"color:#6A737D\\">// [1,2,3]</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">// 然后</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">5</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">6</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">a; </span><span style=\\"color:#6A737D\\">// [1,2,3]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b; </span><span style=\\"color:#6A737D\\">// [4,5,6]</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>b=[4,5,6] 并不影响 a 指向值 [1,2,3] ,除非 b 不是指向数组的引用,而是指向 a 的指针,但在 JavaScript 中不存在这种情况!</p>\\n<p>参考：</p>\\n<p><a href=\\"https://github.com/getify/You-Dont-Know-JS\\" target=\\"_blank\\" rel=\\"noreferrer\\">You Don't Know JS</a></p>\\n"}]},"relativePath":"tags/js/page/2/index.md","filePath":"tags/[slug].md"}`),e={name:"tags/js/page/2/index.md"};function l(p,o,r,t,c,i){return n(),a("div")}const b=s(e,[["render",l]]);export{d as __pageData,b as default};
